+                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id))
+                .toList();
+    }
+
+    static boolean keptMoney(Reservation reservation) {
+        return reservation.amountKept().signum() > 0;
+    }
+}
